def convert_old_duty_config(apps, schema_editor):
    """把旧版写死的 A/B 四件事（销卡、补库存、月底清理、月初解绑）转成 DutyTask，旧的打卡记录标识不变。"""
    from datetime import date

    DutySettings = apps.get_model("catalog", "DutySettings")
    DutyTask = apps.get_model("catalog", "DutyTask")
    obj = DutySettings.objects.order_by("id").first()
    cfg = obj.config if obj and isinstance(obj.config, dict) else {}
    a, b = cfg.get("a_user"), cfg.get("b_user")
    # 旧记录的反馈字段换成新格式：补库存的「补完后库存」放进 qty；清理的两个勾选改成按清单序号
    DutyRecord = apps.get_model("catalog", "DutyRecord")
    for rec in DutyRecord.objects.filter(task__in=("stock", "clean")):
        d = dict(rec.data or {})
        if rec.task == "stock" and "stock" in d:
            if d.get("qty") is not None:
                d["added"] = d["qty"]
            d["qty"] = d.pop("stock")
        if rec.task == "clean" and isinstance(d.get("checks"), dict) and "clean" in d["checks"]:
            c = d["checks"]
            d["checks"] = {"0": bool(c.get("clean")), "1": bool(c.get("notify"))}
        if d != rec.data:
            rec.data = d
            rec.save(update_fields=["data"])
    if not (a or b) or DutyTask.objects.exists():
        return
    try:
        start = date.fromisoformat(cfg.get("rotStart") or "")
    except ValueError:
        start = date.today().replace(day=1)
    first, second = (a, b) if cfg.get("rotFirst", "a") == "a" else (b, a)
    seq = [x for x in (first, second) if x]
    stock_seq = [x for x in ((second, first) if cfg.get("stockMode", "other") == "other" else (first, second)) if x]
    month1 = start.replace(day=1)
    end_who = cfg.get("endWho") or "sell"
    who = {"a": a, "b": b}
    DutyTask.objects.create(key="sell", name="销卡", icon="💳", color="#00704A", sort_order=1, freq_type="daily",
                            start_date=start, assign_mode="rotate" if len(seq) > 1 else "fixed", assignees=seq,
                            qty_enabled=True, qty_label="销卡数量", qty_unit="张", image_mode="optional")
    DutyTask.objects.create(key="stock", name="增加成品号库存", icon="📦", color="#B8873A", sort_order=2,
                            freq_type="daily", start_date=start,
                            assign_mode="rotate" if len(stock_seq) > 1 else "fixed", assignees=stock_seq,
                            qty_enabled=True, qty_label="补完后库存", qty_unit="个", qty_required=True,
                            target_mode="ramp", target_start=int(cfg.get("stockStart") or 200),
                            target_end=int(cfg.get("stockEnd") or 500),
                            target_overrides=cfg.get("stockOverride") or {}, image_mode="optional")
    clean_seq = seq if end_who == "sell" else [x for x in [who.get(end_who)] if x]
    DutyTask.objects.create(key="clean", name="清理卡片 + 通知充值", icon="🧹", color="#3B6EA8", sort_order=3,
                            freq_type="monthly", freq_monthdays=[-1], start_date=month1,
                            assign_mode="rotate" if len(clean_seq) > 1 else "fixed", assignees=clean_seq,
                            checklist=["清理卡片", "通知充值"], image_mode="optional")
    ub = who.get(cfg.get("unbindDefaultWho") or "a")
    DutyTask.objects.create(key="unbind", name="解绑卡片", icon="🔓", color="#7B5EA7", sort_order=4,
                            freq_type="monthly", freq_monthdays=[int(cfg.get("unbindDefaultDay") or 2)],
                            start_date=month1, assign_mode="fixed", assignees=[x for x in [ub] if x],
                            qty_enabled=True, qty_label="解绑数量", qty_unit="张", image_mode="optional")
    swaps = {}
    for k, v in (cfg.get("swaps") or {}).items():
        if who.get(v):
            swaps[k] = who[v]
    obj.config = {"swaps": swaps, "offDays": cfg.get("offDays") or [], "legacy": cfg}
    obj.save(update_fields=["config"])


